import { z } from "zod";
import type {
	GetV1WorkoutsEvents200,
	PostV1Workouts201,
	PutV1WorkoutsWorkoutid200,
} from "@hevy-mcp/hevy-client/types";
import {
	paginationShape,
	nonEmptyId,
	replaceWorkoutExercisesInputShape,
	updateWorkoutInputShape,
	workoutInputShape,
} from "./input-schemas.js";
import type { ToolDefinition } from "./define-tool.js";
import type { ToolRuntime } from "./tool-runtime.js";
import {
	createWorkoutResponse,
	updateWorkoutResponse,
	workoutEventsResponse,
	workoutResponse,
	workoutsResponse,
} from "../utils/response-contracts.js";
import {
	createAnnotations,
	readOnlyAnnotations,
	updateAnnotations,
} from "../utils/tool-annotations.js";

import type { InferToolParams } from "../utils/tool-helpers.js";
import { buildWorkoutUpdatePayload } from "./mutation-semantics.js";
import { isExpectedListPageNotFound } from "../utils/hevy-error-policy.js";

const getWorkoutsSchema = paginationShape({
	defaultPageSize: 5,
	maxPageSize: 10,
	integerPage: false,
});
type GetWorkoutsParams = InferToolParams<typeof getWorkoutsSchema>;

const getWorkoutSchema = { workout_id: nonEmptyId } as const;
type GetWorkoutParams = InferToolParams<typeof getWorkoutSchema>;

const getWorkoutEventsSchema = {
	...paginationShape({ defaultPageSize: 5, maxPageSize: 10 }),
	since: z.string().default("1970-01-01T00:00:00Z"),
} as const;
type GetWorkoutEventsParams = InferToolParams<typeof getWorkoutEventsSchema>;

const createWorkoutSchema = workoutInputShape;
type CreateWorkoutParams = InferToolParams<typeof createWorkoutSchema>;

const updateWorkoutSchema = updateWorkoutInputShape;
type UpdateWorkoutParams = InferToolParams<typeof updateWorkoutSchema>;

const replaceWorkoutExercisesSchema = replaceWorkoutExercisesInputShape;
type ReplaceWorkoutExercisesParams = InferToolParams<
	typeof replaceWorkoutExercisesSchema
>;

export const workoutToolDefinitions = [
	{
		name: "get-workouts",
		feature: "workouts" as const,
		operation: "list" as const,
		description:
			"Read-only. Lists compact workout summaries newest first. Use get-workout for exercises and sets; results are paginated.",
		inputSchema: getWorkoutsSchema,
		outputSchema: workoutsResponse.outputSchema,
		annotations: readOnlyAnnotations("Get Workouts"),
		kind: "read" as const,
		responseContract: workoutsResponse,
		execute: async (runtime: ToolRuntime, args: GetWorkoutsParams) => {
			const data = await runtime.getOperations().workouts.list.execute(
				{
					page: args.page,
					pageSize: args.page_size,
				},
				runtime.execution,
			);
			return data;
		},
	},
	{
		name: "get-workout",
		feature: "workouts" as const,
		operation: "get" as const,
		description:
			"Read-only. Gets one workout with exercises and sets by workout_id. Use get-workouts to discover IDs.",
		inputSchema: getWorkoutSchema,
		outputSchema: workoutResponse.outputSchema,
		annotations: readOnlyAnnotations("Get Workout"),
		kind: "read" as const,
		responseContract: workoutResponse,
		execute: async (runtime: ToolRuntime, args: GetWorkoutParams) => {
			const data = await runtime
				.getOperations()
				.workouts.get.execute(
					{ workoutId: args.workout_id },
					runtime.execution,
				);
			return { ...data, workout_id: args.workout_id };
		},
	},
	{
		name: "get-workout-events",
		feature: "workouts" as const,
		operation: "sync" as const,
		description:
			"Read-only. Lists workout update and deletion events since a timestamp for incremental sync; results are paginated.",
		inputSchema: getWorkoutEventsSchema,
		outputSchema: workoutEventsResponse.outputSchema,
		annotations: readOnlyAnnotations("Get Workout Events"),
		kind: "read" as const,
		responseContract: workoutEventsResponse,
		execute: async (runtime: ToolRuntime, args: GetWorkoutEventsParams) => {
			try {
				const data: GetV1WorkoutsEvents200 = await runtime
					.getClient()
					.getWorkoutEvents({
						page: args.page,
						pageSize: args.page_size,
						since: args.since,
					});
				return {
					events: data?.events,
					since: args.since,
					page: args.page,
					pageCount: data?.page_count,
				};
			} catch (error) {
				if (isExpectedListPageNotFound(error, args.page)) {
					return {
						events: [],
						since: args.since,
						page: args.page,
						expected404Outcome: "end_of_list",
					};
				}
				throw error;
			}
		},
	},
	{
		name: "create-workout",
		feature: "workouts" as const,
		operation: "create" as const,
		description:
			"Writes a completed workout. Requires exercise-template IDs and UTC times. Retries can create duplicates.",
		inputSchema: createWorkoutSchema,
		annotations: createAnnotations("Create Workout"),
		kind: "write" as const,
		responseContract: createWorkoutResponse,
		execute: async (runtime: ToolRuntime, args: CreateWorkoutParams) => {
			const data: PostV1Workouts201 = await runtime.getClient().createWorkout({
				workout: args.workout,
			});
			return data;
		},
	},
	{
		name: "update-workout",
		feature: "workouts" as const,
		operation: "update" as const,
		description:
			"Mutates workout metadata by ID. Omitted fields and all exercises remain unchanged.",
		inputSchema: updateWorkoutSchema,
		annotations: updateAnnotations("Update Workout"),
		kind: "write" as const,
		responseContract: updateWorkoutResponse,
		execute: async (runtime: ToolRuntime, args: UpdateWorkoutParams) => {
			const client = runtime.getClient();
			const current = await client.getWorkout(args.workout_id);
			const payload = buildWorkoutUpdatePayload(current, args.workout);
			const data: PutV1WorkoutsWorkoutid200 = await client.updateWorkout(
				args.workout_id,
				{ workout: payload },
			);
			return { workout: data, workout_id: args.workout_id };
		},
	},
	{
		name: "replace-workout-exercises",
		feature: "workouts" as const,
		operation: "update" as const,
		description:
			"Mutates a workout by replacing all exercises and sets. Workout metadata remains unchanged.",
		inputSchema: replaceWorkoutExercisesSchema,
		annotations: updateAnnotations("Replace Workout Exercises"),
		kind: "write" as const,
		responseContract: updateWorkoutResponse,
		execute: async (
			runtime: ToolRuntime,
			args: ReplaceWorkoutExercisesParams,
		) => {
			const client = runtime.getClient();
			const current = await client.getWorkout(args.workout_id);
			const payload = buildWorkoutUpdatePayload(
				current,
				{},
				args.workout.exercises,
			);
			const data: PutV1WorkoutsWorkoutid200 = await client.updateWorkout(
				args.workout_id,
				{ workout: payload },
			);
			return { workout: data, workout_id: args.workout_id };
		},
	},
] satisfies readonly ToolDefinition<Record<string, z.ZodTypeAny>, unknown>[];

function createExecutionError(options: ExecutionErrorOptions): HevyHttpError {
	const { deadlineExceeded, canceled } = options;
	return new HevyHttpError(
		deadlineExceeded
			? "Hevy API request deadline exceeded"
			: canceled
				? "Hevy API request was canceled"
				: "Hevy API network request failed",
		{
			method: options.method,
			endpoint: options.endpoint,
			code: deadlineExceeded
				? HEVY_DEADLINE_EXCEEDED_ERROR_CODE
				: canceled
					? HEVY_REQUEST_ABORTED_ERROR_CODE
					: (options.code ?? "ERR_NETWORK"),
			phase: options.phase,
			operationSafety: options.safety,
			commitState: commitStateFor(
				options.safety,
				options.phase,
				options.responseConfirmed ?? false,
			),
			safeToRetry: false,
			outcome: deadlineExceeded
				? "deadline_exceeded"
				: canceled
					? "cancelled"
					: "terminal_failure",
			cause: options.cause,
		},
	);
}

function applyExecutionMetadata(
	error: HevyHttpError,
	phase: HevyRequestPhase,
	safety: HevyOperationSafety,
	commitState: HevyCommitState,
	safeToRetry: boolean,
	outcome: HevyApiOutcome,
): void {
	error.setExecutionMetadata({
		phase,
		operationSafety: safety,
		commitState,
		safeToRetry,
		outcome,
	});
}

/** Rebind caller-supplied errors to the sanitized request identity. */
function normalizeHevyHttpError(
	error: HevyHttpError,
	method: string,
	endpoint: string,
): HevyHttpError {
	const normalized = new HevyHttpError(error.message, {
		status: error.status,
		statusText: error.statusText,
		data: error.data,
		headers: error.headers,
		method,
		endpoint,
		code: error.code,
		cause: error.cause,
		phase: error.phase,
		operationSafety: error.operationSafety,
		commitState: error.commitState,
		safeToRetry: error.safeToRetry,
		outcome: error.outcome,
	});
	normalized.hevyRetryCount = error.hevyRetryCount;
	normalized.hevyRetryExhausted = error.hevyRetryExhausted;
	return normalized;
}

function requestOptions(
	options: HevyRequestOptions | undefined,
	client: KubbClient,
): InternalRequestControl & { client: KubbClient; signal?: AbortSignal } {
	return {
		client,
		...(options?.signal ? { signal: options.signal } : {}),
		...(options?.deadline !== undefined
			? { hevyDeadline: options.deadline }
			: {}),
	};
}

interface RequestAttemptExecutionOptions {
	apiKey: string;
	fetchImplementation: typeof globalThis.fetch;
	normalized: RequestConfig<unknown> & InternalRequestControl;
	url: URL;
	method: string;
	endpoint: string;
	safety: HevyOperationSafety;
	deadline: number;
	executionSignal: AbortSignal;
	startedAt: number;
	retryCount: number;
	observationScope: HevyRequestObservationScope | undefined;
	onRequestComplete: HevyClientOptions["onRequestComplete"];
}

type RequestAttemptOutcome<TData> =
	| {
			readonly ok: true;
			readonly result: ResponseConfig<TData>;
	  }
	| {
			readonly ok: false;
			readonly cause: unknown;
			readonly phase: HevyRequestPhase;
			readonly responseConfirmed: boolean;
	  };

/** Execute one dispatch/response attempt and retain its safe phase state. */
async function executeRequestAttempt<TData>(
	options: RequestAttemptExecutionOptions,
): Promise<RequestAttemptOutcome<TData>> {
	let phase: HevyRequestPhase = "before-dispatch";
	let responseConfirmed = false;
	const attemptController = new AbortController();
	const abortAttempt = () =>
		attemptController.abort(options.executionSignal.reason);
	options.executionSignal.addEventListener("abort", abortAttempt, {
		once: true,
	});
	try {
		const result = await runRequestObservation(
			options.observationScope,
			async () => {
				const headers = new Headers({ "api-key": options.apiKey });
				if (
					options.normalized.data !== undefined &&
					!(options.normalized.data instanceof FormData)
				) {
					headers.set("content-type", "application/json");
				}
				const requestInit: RequestInit = {
					method: options.method,
					headers,
					redirect: "manual",
					body:
						options.normalized.data instanceof FormData
							? options.normalized.data
							: options.normalized.data === undefined
								? undefined
								: JSON.stringify(options.normalized.data),
					signal: attemptController.signal,
				};
				let fetchPromise: Promise<Response>;
				try {
					const fetchImplementation = options.fetchImplementation;
					fetchPromise = Promise.resolve(
						fetchImplementation(options.url, requestInit),
					);
				} catch (error) {
					phase = "before-dispatch";
					throw error;
				}
				phase = "dispatch";
				const response = await withTimeout(
					fetchPromise,
					remainingDeadlineMs(options.deadline),
					() =>
						attemptController.abort(
							new DOMException("Operation timed out", "TimeoutError"),
						),
					attemptController.signal,
				);
				phase = "response-headers";
				phase = "response-content";
				const data = await withTimeout(
					parseResponseData(response),
					remainingDeadlineMs(options.deadline),
					() =>
						attemptController.abort(
							new DOMException("Operation timed out", "TimeoutError"),
						),
					attemptController.signal,
				);
				if (!response.ok) {
					throw new HevyHttpError(
						`Hevy API request failed (HTTP ${response.status})`,
						{
							status: response.status,
							statusText: response.statusText,
							data,
							headers: response.headers,
							method: options.method,
							endpoint: options.endpoint,
							phase,
							operationSafety: options.safety,
							commitState: commitStateFor(options.safety, phase, false),
							safeToRetry: false,
						},
					);
				}
				responseConfirmed = true;
				const observation: HevyRequestObservation = {
					method: options.method,
					endpoint: options.endpoint,
					status: response.status,
					durationMs: Date.now() - options.startedAt,
					retryCount: options.retryCount,
					outcome: "success",
					phase: "completed",
					operationSafety: options.safety,
					commitState: "confirmed",
					safeToRetry: false,
				};
				finishRequestObservation(options.observationScope, observation);
				emitRequestObservation(options.onRequestComplete, observation);
				return {
					data: data as TData,
					status: response.status,
					statusText: response.statusText,
					headers: response.headers,
				};
			},
		);
		return { ok: true, result };
	} catch (cause) {
		return { ok: false, cause, phase, responseConfirmed };
	} finally {
		options.executionSignal.removeEventListener("abort", abortAttempt);
	}
}

interface AttemptFailureTransitionOptions {
	cause: unknown;
	method: string;
	endpoint: string;
	page: number | undefined;
	safety: HevyOperationSafety;
	phase: HevyRequestPhase;
	responseConfirmed: boolean;
	executionSignal: ReturnType<typeof createExecutionSignal>;
	deadline: number;
	retryCount: number;
	maxGetRetries: number;
	startedAt: number;
	observationScope: HevyRequestObservationScope | undefined;
	clientOptions: HevyClientOptions;
}

interface AttemptFailureTransition {
	readonly retry: boolean;
	readonly error: HevyHttpError;
	readonly retryCount: number;
	readonly delayMs?: number;
	readonly retryWaitScope?: HevyRetryWaitScope;
}

function createAttemptFailureError(
	options: AttemptFailureTransitionOptions,
	failure: ExecutionFailureState,
): HevyHttpError {
	if (isHevyHttpError(options.cause)) {
		return normalizeHevyHttpError(
			options.cause,
			options.method,
			options.endpoint,
		);
	}
	return createExecutionError({
		method: options.method,
		endpoint: options.endpoint,
		safety: options.safety,
		phase: options.phase,
		deadlineExceeded: failure.deadlineExceeded,
		canceled: failure.canceled,
		responseConfirmed: options.responseConfirmed,
		code: failure.attemptTimedOut ? "ETIMEDOUT" : getNetworkCode(options.cause),
		cause: options.cause,
	});
}

function canRetryAttempt(
	options: AttemptFailureTransitionOptions,
	failure: ExecutionFailureState,
	error: HevyHttpError,
): boolean {
	return (
		!failure.deadlineExceeded &&
		!failure.canceled &&
		options.safety !== "non-idempotent-write" &&
		canRetryOperation(options.safety, options.phase) &&
		isRetryable(error) &&
		remainingDeadlineMs(options.deadline) > 0
	);
}

function failureMetadataOutcome(
	failure: ExecutionFailureState,
): HevyApiOutcome {
	if (failure.deadlineExceeded) return "deadline_exceeded";
	if (failure.canceled) return "cancelled";
	return "terminal_failure";
}

function applyRetryExhaustion(
	error: HevyHttpError,
	options: AttemptFailureTransitionOptions,
	safeToRetry: boolean,
): boolean {
	if (!safeToRetry || options.retryCount < options.maxGetRetries) return false;
	error.hevyRetryExhausted = true;
	error.hevyRetryCount = options.retryCount;
	error.code = HEVY_RETRY_EXHAUSTED_ERROR_CODE;
	error.setExecutionMetadata({
		phase: error.phase,
		operationSafety: error.operationSafety,
		commitState: error.commitState,
		safeToRetry: false,
		outcome: "terminal_failure",
	});
	return true;
}

