import { readFile } from "node:fs/promises";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
	loadTopology,
	releaseConsumers,
	workspaceById,
	workspaceByName,
} from "./repository-control-plane.mjs";

const execFileAsync = promisify(execFile);
const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const sinceIndex = process.argv.indexOf("--since");
const since = sinceIndex >= 0 ? process.argv[sinceIndex + 1] : "origin/main";

if (!since) throw new Error("Missing value for --since");

const topology = loadTopology(root);
const releaseTriggerFiles = new Map(
	topology.release.triggers.map((trigger) => [
		trigger.path,
		workspaceById(topology, trigger.workspace).name,
	]),
);
const releaseBumps = new Set(["patch", "minor", "major"]);

const { stdout } = await execFileAsync(
	"git",
	["diff", "--name-only", "--diff-filter=ACMRD", `${since}...HEAD`],
	{ cwd: root },
);
const changedFiles = stdout.trim().split("\n").filter(Boolean);

async function readPackageName(packagePath) {
	const manifestPath = `${packagePath}/package.json`;
	let contents;

	try {
		contents = await readFile(resolve(root, manifestPath), "utf8");
	} catch {
		try {
			const result = await execFileAsync(
				"git",
				["show", `${since}:${manifestPath}`],
				{ cwd: root },
			);
			contents = result.stdout;
		} catch {
			return undefined;
		}
	}

	try {
		const packageJson = JSON.parse(contents);
		return typeof packageJson.name === "string" ? packageJson.name : undefined;
	} catch {
		return undefined;
	}
}

const changedPackagePaths = new Set();
for (const file of changedFiles) {
	const match = file.match(/^packages\/([^/]+)(?:\/|$)/);
	if (match) changedPackagePaths.add(`packages/${match[1]}`);
}

const changedPackages = new Map();
for (const path of changedPackagePaths) {
	const packageName = await readPackageName(path);
	if (packageName) changedPackages.set(path, packageName);
}
for (const file of changedFiles) {
	const packageName = releaseTriggerFiles.get(file);
	if (packageName) changedPackages.set(file, packageName);
}

if (changedPackages.size === 0) {
	console.log("No workspace package changes require a package changeset.");
	process.exit(0);
}

const { stdout: changesetDiff } = await execFileAsync(
	"git",
	[
		"diff",
		"--name-status",
		"--find-renames",
		`${since}...HEAD`,
		"--",
		".changeset",
	],
	{ cwd: root },
);
const changedChangesetFiles = changesetDiff
	.trim()
	.split("\n")
	.filter(Boolean)
	.flatMap((line) => {
		const [status, sourcePath, destinationPath] = line.split("\t");
		if (status === "A" || status === "M") return [sourcePath];
		if (status.startsWith("R") && status !== "R100") {
			return [destinationPath];
		}
		return [];
	})
	.filter((file) => /^\.changeset\/[^/]+\.md$/.test(file));

const changesetReleases = new Set();
const emptyChangesetFiles = [];
let changedChangesetCount = 0;
for (const file of changedChangesetFiles) {
	let contents;
	try {
		contents = await readFile(resolve(root, file), "utf8");
	} catch {
		continue;
	}
	changedChangesetCount += 1;
	const fileReleases = new Set();
	const frontmatter = contents.match(/^---\s*\n([\s\S]*?)\n---/);
	if (frontmatter) {
		for (const line of frontmatter[1].split("\n")) {
			const match = line.match(
				/^\s*(?:"([^"]+)"|'([^']+)'|([@A-Za-z0-9._/-]+))\s*:\s*([A-Za-z]+)\s*$/,
			);
			if (!match) continue;
			const packageName = match[1] ?? match[2] ?? match[3];
			const bump = match[4];
			if (!releaseBumps.has(bump)) continue;
			fileReleases.add(packageName);
			changesetReleases.add(packageName);
		}
	}
	if (fileReleases.size === 0) emptyChangesetFiles.push(file);
}

if (changedChangesetCount === 0) {
	throw new Error(
		`Changed workspace packages need a changeset added or modified by this branch:\n${[...changedPackages.entries()].map(([path, packageName]) => `- ${path} -> ${packageName}`).join("\n")}`,
	);
}

if (emptyChangesetFiles.length > 0) {
	throw new Error(
		`Empty Changesets cannot accompany release-triggering changes:\n${emptyChangesetFiles.map((file) => `- ${file}`).join("\n")}\nRelease-triggering changes require non-empty bumps:\n${[...changedPackages.entries()].map(([path, packageName]) => `- ${path} -> ${packageName}`).join("\n")}`,
	);
}

const missing = [...changedPackages.entries()]
	.filter(([, packageName]) => !changesetReleases.has(packageName))
	.map(([path, packageName]) => `${path} -> ${packageName}`);

if (missing.length > 0) {
	throw new Error(
		`Changed workspace packages need a changeset naming the same package:\n${missing.map((entry) => `- ${entry}`).join("\n")}`,
	);
}

function getTransitiveConsumers(packageName) {
	let workspace;
	try {
		workspace = workspaceByName(topology, packageName);
	} catch {
		return [];
	}
	return releaseConsumers(topology, workspace.id).map(
		(consumer) => workspaceById(topology, consumer).name,
	);
}

const cascadeRoots = topology.release.bundles.map(
	(bundle) => workspaceById(topology, bundle.workspace).name,
);
const incompleteCascades = cascadeRoots
	.filter((packageName) => changesetReleases.has(packageName))
	.map((packageName) => ({
		packageName,
		missing: getTransitiveConsumers(packageName).filter(
			(consumer) => !changesetReleases.has(consumer),
		),
	}))
	.filter(({ missing }) => missing.length > 0);

if (incompleteCascades.length > 0) {
	throw new Error(
		`Bundled release cascades must include every transitive shipped consumer with at least a patch bump:\n${incompleteCascades
			.map(
				({ packageName, missing }) =>
					`- ${packageName} -> missing ${missing.join(", ")}`,
			)
			.join("\n")}`,
	);
}

const allowedReleases = new Set();
for (const packageName of changedPackages.values()) {
	allowedReleases.add(packageName);
	for (const consumer of getTransitiveConsumers(packageName)) {
		allowedReleases.add(consumer);
	}
}
const unrelatedReleases = [...changesetReleases].filter(
	(packageName) => !allowedReleases.has(packageName),
);
if (unrelatedReleases.length > 0) {
	throw new Error(
		`Changesets must not couple unrelated package releases:\n${unrelatedReleases
			.map((packageName) => `- ${packageName}`)
			.join("\n")}`,
	);
}

console.log(
	`Package changeset coverage passed for ${changedPackages.size} workspace package(s).`,
);

export {
	createSafeErrorDiagnostic,
	type SafeErrorCategory,
	type SafeErrorDiagnostic,
	type SafeStackFrame,
} from "./error-policy.js";

import {
	diagnosticEndpointIdentity,
	HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
	HEVY_REQUEST_ABORTED_ERROR_CODE,
	HEVY_RETRY_EXHAUSTED_ERROR_CODE,
	isHevyHttpError,
} from "@hevy-mcp/hevy-client";
import type {
	HevyCommitState,
	HevyExecutionOutcome,
	HevyOperationSafety,
	HevyRequestPhase,
} from "@hevy-mcp/hevy-client";

/** Specific error types for categorization and metrics. */
export enum ErrorType {
	API_ERROR = "API_ERROR",
	RATE_LIMIT = "RATE_LIMIT",
	VALIDATION_ERROR = "VALIDATION_ERROR",
	NOT_FOUND = "NOT_FOUND",
	NETWORK_ERROR = "NETWORK_ERROR",
	UNKNOWN_ERROR = "UNKNOWN_ERROR",
}

type HeaderValue = string | number | string[] | undefined;
type HeaderMap = { [key: string]: HeaderValue };

export type SafeErrorCategory =
	| "AggregateError"
	| "DOMException"
	| "Error"
	| "EvalError"
	| "HevyHttpError"
	| "RangeError"
	| "ReferenceError"
	| "SyntaxError"
	| "TypeError"
	| "URIError"
	| "UnknownError";

export interface SafeStackFrame {
	source: SafeSourceId;
	line: number;
	column: number;
}

export interface SafeErrorDiagnostic {
	category: SafeErrorCategory;
	code?: string;
	status?: number;
	method?: string;
	endpoint?: string;
	frames?: SafeStackFrame[];
	phase?: HevyRequestPhase;
	operation_safety?: HevyOperationSafety;
	commit_state?: HevyCommitState;
	safe_to_retry?: boolean;
	outcome?: HevyExecutionOutcome;
}

type SafeSourceId =
	| "error-handler"
	| "hevy-client"
	| "index"
	| "server"
	| "worker";

type RetryAwareError = {
	hevyRetryCount?: number;
	hevyRetryExhausted?: boolean;
};

const ABORT_TIMEOUT_METADATA = {
	AbortError: {
		code: HEVY_REQUEST_ABORTED_ERROR_CODE,
		outcome: "cancelled" as const,
	},
	TimeoutError: {
		code: HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
		outcome: "deadline_exceeded" as const,
	},
} as const;

type AbortTimeoutErrorMetadata =
	(typeof ABORT_TIMEOUT_METADATA)[keyof typeof ABORT_TIMEOUT_METADATA] & {
		name: keyof typeof ABORT_TIMEOUT_METADATA;
	};

/** Map raw cancellation errors to their bounded execution metadata. */
function getAbortTimeoutErrorMetadata(
	error: unknown,
): AbortTimeoutErrorMetadata | undefined {
	try {
		if (!(error instanceof Error)) return undefined;
		const name = error.name as keyof typeof ABORT_TIMEOUT_METADATA;
		const metadata = ABORT_TIMEOUT_METADATA[name];
		return metadata ? { name, ...metadata } : undefined;
	} catch {
		return undefined;
	}
}

const SAFE_ERROR_CODES = new Set([
	"EAI_AGAIN",
	"ECONNABORTED",
	"ECONNREFUSED",
	"ECONNRESET",
	"ENETUNREACH",
	"ENOTFOUND",
	"ERR_NETWORK",
	"ERR_SOCKET_TIMEOUT",
	"ETIMEDOUT",
	"HEVY_INVALID_ENDPOINT",
	HEVY_REQUEST_ABORTED_ERROR_CODE,
	HEVY_RETRY_EXHAUSTED_ERROR_CODE,
	HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
]);

const SAFE_HTTP_METHODS = new Set([
	"DELETE",
	"GET",
	"HEAD",
	"OPTIONS",
	"PATCH",
	"POST",
	"PUT",
]);

const SAFE_SOURCE_SUFFIXES: ReadonlyArray<readonly [string, SafeSourceId]> = [
	["/packages/core/src/utils/error-handler.ts", "error-handler"],
	["/packages/hevy-client/src/hevy-client-kubb.ts", "hevy-client"],
	["/packages/node/src/index.ts", "index"],
	["/packages/core/src/server.ts", "server"],
	["/packages/worker/src/worker.ts", "worker"],
];

const PROJECT_PATH_MARKER = "/hevy-mcp/";
const MAX_STACK_POSITION = 1_000_000;

function normalizeHeaderValue(value: unknown): string | undefined {
	if (typeof value === "string") {
		const trimmed = value.trim();
		return trimmed.length > 0 ? trimmed : undefined;
	}

	if (typeof value === "number" && Number.isFinite(value)) {
		return String(value);
	}

	if (Array.isArray(value) && value.length > 0) {
		return normalizeHeaderValue(value[0]);
	}

	return undefined;
}

function getHeaderValue(headers: unknown, key: string): string | undefined {
	try {
		if (!headers || typeof headers !== "object") return undefined;

		if (
			"get" in headers &&
			typeof (headers as { get?: unknown }).get === "function"
		) {
			const value = (headers as { get: (headerName: string) => unknown }).get(
				key,
			);
			return normalizeHeaderValue(value);
		}

		const headerRecord = headers as HeaderMap;
		return normalizeHeaderValue(
			headerRecord[key] ??
				headerRecord[key.toLowerCase()] ??
				headerRecord[key.toUpperCase()],
		);
	} catch {
		return undefined;
	}
}

/** Extract a valid HTTP status without retaining untrusted error metadata. */
export function extractErrorStatus(error: unknown): number | undefined {
	try {
		if (!isHevyHttpError(error)) return undefined;
		return error.status !== undefined &&
			Number.isInteger(error.status) &&
			error.status >= 100 &&
			error.status <= 599
			? error.status
			: undefined;
	} catch {
		return undefined;
	}
}

/** Return whether the client exhausted its bounded transient retry policy. */
export function isRetryExhausted(error: unknown): boolean {
	try {
		return (
			!!error &&
			typeof error === "object" &&
			(error as RetryAwareError).hevyRetryExhausted === true
		);
	} catch {
		return false;
	}
}

/** Interpret a Retry-After header as seconds from the supplied current time. */
export function getRetryAfterSeconds(
	error: unknown,
	now = Date.now(),
): number | undefined {
	try {
		if (!isHevyHttpError(error)) return undefined;
		const retryAfterHeader = getHeaderValue(error.headers, "retry-after");
		if (!retryAfterHeader) return undefined;

		const seconds = Number(retryAfterHeader);
		if (Number.isFinite(seconds) && seconds >= 0) return seconds;

		const retryAtMillis = Date.parse(retryAfterHeader);
		if (Number.isNaN(retryAtMillis)) return undefined;
		return Math.ceil(Math.max(0, retryAtMillis - now) / 1000);
	} catch {
		return undefined;
	}
}

/** Map bounded Hevy HTTP statuses to stable user-facing messages. */
export function getStatusErrorMessage(status?: number): string | null {
	if (status === 401 || status === 403) {
		return "The Hevy API key is invalid or has expired. Check HEVY_API_KEY.";
	}
	if (status === 404) return "The requested resource was not found in Hevy.";
	if (status === 409) {
		return "A conflict occurred (e.g., a body measurement already exists for this date). Use the update tool instead.";
	}
	if (status === 422) {
		return "The request failed Hevy validation. Check the field values and try again.";
	}
	if (status === 429) return "Rate limited by Hevy. Please wait and retry.";
	if (status !== undefined && status >= 500 && status <= 599) {
		return "Hevy API experienced an error. Please retry later.";
	}
	return null;
}

function formatSecondsLabel(seconds: number): string {
	const roundedSeconds = Math.max(0, Math.round(seconds));
	const suffix = roundedSeconds === 1 ? "" : "s";
	return `${roundedSeconds} second${suffix}`;
}

function getRateLimitMessage(error: unknown): string {
	const seconds = getRetryAfterSeconds(error);
	if (seconds !== undefined) {
		return `Rate limited by Hevy (HTTP 429). Please wait about ${formatSecondsLabel(seconds)} before retrying.`;
	}
	return "Rate limited by Hevy (HTTP 429). Please wait and retry your request.";
}

function getRetryExhaustedMessage(error: unknown): string {
	let retryCount: unknown;
	try {
		retryCount =
			typeof error === "object" && error !== null
				? (error as RetryAwareError).hevyRetryCount
				: undefined;
	} catch {
		retryCount = undefined;
	}
	const attemptCount =
		typeof retryCount === "number" && Number.isFinite(retryCount)
			? retryCount + 1
			: undefined;
	if (attemptCount) {
		return `Unable to complete the request after ${attemptCount} attempts to the Hevy API due to transient failures. Please try again shortly.`;
	}
	return "Unable to complete the request after multiple attempts to the Hevy API due to transient failures. Please try again shortly.";
}

/** Classify an error using bounded status, names, and supplied text. */
export function determineErrorType(error: unknown, message: string): ErrorType {
	if (isRetryExhausted(error)) return ErrorType.NETWORK_ERROR;
	if (extractErrorStatus(error) === 429) return ErrorType.RATE_LIMIT;

	let originalMessage = "";
	let nameLower = "";
	try {
		if (error instanceof Error) {
			originalMessage = error.message.slice(0, 512);
			nameLower = error.name.toLowerCase();
		}
	} catch {
		originalMessage = "";
		nameLower = "";
	}
	const classificationText = `${message}\n${originalMessage}`.toLowerCase();

	if (
		nameLower.includes("network") ||
		classificationText.includes("network") ||
		classificationText.includes("fetch") ||
		classificationText.includes("timeout")
	) {
		return ErrorType.NETWORK_ERROR;
	}
	if (
		nameLower.includes("validation") ||
		classificationText.includes("validation") ||
		classificationText.includes("invalid") ||
		classificationText.includes("required")
	) {
		return ErrorType.VALIDATION_ERROR;
	}
	if (
		classificationText.includes("not found") ||
		classificationText.includes("404") ||
		classificationText.includes("does not exist")
	) {
		return ErrorType.NOT_FOUND;
	}
	if (
		nameLower.includes("api") ||
		classificationText.includes("api") ||
		classificationText.includes("server error") ||
		classificationText.includes("500")
	) {
		return ErrorType.API_ERROR;
	}
	return ErrorType.UNKNOWN_ERROR;
}

function classifyError(error: unknown): SafeErrorCategory {
	if (isHevyHttpError(error)) return "HevyHttpError";
	if (error instanceof TypeError) return "TypeError";
	if (error instanceof RangeError) return "RangeError";
	if (error instanceof ReferenceError) return "ReferenceError";
	if (error instanceof SyntaxError) return "SyntaxError";
	if (error instanceof URIError) return "URIError";
	if (error instanceof EvalError) return "EvalError";
	if (error instanceof AggregateError) return "AggregateError";
	if (typeof DOMException !== "undefined" && error instanceof DOMException) {
		return "DOMException";
	}
	if (error instanceof Error) return "Error";
	return "UnknownError";
}

function getSafeCode(error: unknown): string | undefined {
	const abortTimeout = getAbortTimeoutErrorMetadata(error);
	if (abortTimeout) return abortTimeout.code;
	if (!error || typeof error !== "object" || !("code" in error)) {
		return undefined;
	}
	const code = error.code;
	return typeof code === "string" && SAFE_ERROR_CODES.has(code)
		? code
		: undefined;
}

function getSafeMethod(error: unknown): string | undefined {
	if (!isHevyHttpError(error)) return undefined;
	const method = error.method.toUpperCase();
	return SAFE_HTTP_METHODS.has(method) ? method : undefined;
}

function getSafeEndpoint(error: unknown): string | undefined {
	if (!isHevyHttpError(error)) return undefined;
	return diagnosticEndpointIdentity(error.endpoint);
}

function getExecutionFields(
	error: unknown,
): Pick<
	SafeErrorDiagnostic,
	"phase" | "operation_safety" | "commit_state" | "safe_to_retry" | "outcome"
> {
	if (!isHevyHttpError(error)) {
		const abortTimeout = getAbortTimeoutErrorMetadata(error);
		if (abortTimeout) {
			return {
