export { HEVY_REQUEST_ABORTED_ERROR_CODE };
export { HEVY_DEADLINE_EXCEEDED_ERROR_CODE };

const RETRY_BACKOFF_MAX_MS = 5_000;
export const SAFE_OBSERVATION_CODES = new Set([
	"EAI_AGAIN",
	"ECONNABORTED",
	"ECONNREFUSED",
	"ECONNRESET",
	"ENETUNREACH",
