		),
	);
	const client = createHevyClient({
		apiKey: "api-key-secret",
		fetch: fetchMock,
		maxGetRetries: 0,
		onRequestComplete: (observation) => observations.push(observation),
	});

	let thrown: unknown;
	try {
		await client.getUserInfo();
	} catch (error) {
		thrown = error;
	}

	expect(thrown).toMatchObject({
